import Link from 'next/link';
import {getVendorMemberships} from '@/lib/vendors';
import {requireUser} from '@/lib/auth';
import {prisma} from '@/lib/prisma';
export const dynamic='force-dynamic';
export default async function VendorDashboard(){const user=await requireUser();const memberships=await getVendorMemberships(user.id);if(!memberships.length)return <main className="site-shell py-20"><div className="mx-auto max-w-xl text-center"><p className="eyebrow">SELLER SPACE</p><h1 className="mt-4 text-3xl font-bold">Your seller account is not active</h1><p className="mt-3 text-slate-400">Submit an application and wait for admin approval before managing products.</p><Link href="/sell/apply" className="btn-primary mt-7 inline-flex">Apply to sell</Link></div></main>;const m=memberships[0];const [products,ledger]=await Promise.all([prisma.template.count({where:{vendorId:m.vendorId}}),prisma.vendorLedgerEntry.aggregate({where:{vendorId:m.vendorId},_sum:{amountMmk:true}})]);return <main className="admin-content"><p className="eyebrow">VENDOR SPACE</p><h1 className="admin-title">{m.vendor.storeName}</h1><p className="mt-2 text-sm text-slate-400">{m.role} · verified seller</p><div className="admin-stat-grid mt-8"><Stat label="Products" value={products}/><Stat label="Ledger balance" value={`${(ledger._sum.amountMmk||0).toLocaleString()} MMK`}/><Stat label="Memberships" value={memberships.length}/></div><div className="mt-8 grid gap-4 md:grid-cols-3"><Link className="admin-panel" href={`/vendor/products?vendorId=${m.vendorId}`}>Manage products →</Link><Link className="admin-panel" href={`/vendor/earnings?vendorId=${m.vendorId}`}>View earnings →</Link><Link className="admin-panel" href={`/vendor/payouts?vendorId=${m.vendorId}`}>Payouts →</Link></div></main>}
function Stat({label,value}:{label:string;value:string|number}){return <div className="admin-stat"><p className="text-2xl font-bold">{value}</p><p className="mt-1 text-xs text-slate-500">{label}</p></div>}
